  async function check_if_contact_has_chat(user_email, contact, platform2) {
    const res = await frappe.call({
      type: "GET",
      method: "clefincode_chat.api.api_1_2_1.api.check_if_contact_has_chat",
      args: {
        user_email,
        contact,
        platform: platform2
      }
    });
    return await res.message;
  }
  async function check_if_contact_has_whatsapp_chat(default_whatsapp_number, default_whatsapp_type, contact, platform2, user_email) {
    const res = await frappe.call({
      type: "GET",
      method: "clefincode_chat.api.api_1_2_1.api.check_if_contact_has_whatsapp_chat",
      args: {
        default_whatsapp_number,
        default_whatsapp_type,
        contact,
        platform: platform2,
        user_email
      }
    });
    return await res.message.results[0];
  }

