    async handle_upload_file(file) {
      const max_upload_size = 100 * 1024 * 1024;
      if (file.file_obj && file.file_obj.size > max_upload_size) {
        frappe.msgprint(__("Please choose a file up to 100 MB."));
        return;
      }
      const dataurl = await frappe.dom.file_to_base64(file.file_obj);
      file.dataurl = dataurl;
      file.name = file.file_obj.name;
      return this.upload_file(file);
    }
    upload_file(file) {
      const me2 = this;
      return new Promise((resolve, reject) => {
        show_overlay("Uploading...");
        let xhr = new XMLHttpRequest();
        xhr.upload.addEventListener("load", () => {
          resolve();
        });
        xhr.addEventListener("error", () => {
          hide_overlay();
          reject(frappe.throw(__("Internal Server Error")));
        });
        xhr.onreadystatechange = () => {
          if (xhr.readyState == XMLHttpRequest.DONE) {
            if (xhr.status === 200) {
              let r = null;
              let file_doc = null;
              try {
                r = JSON.parse(xhr.responseText);
                if (r.message.doctype === "File") {
                  file_doc = r.message;
                }
              } catch (e) {
                r = xhr.responseText;
              }
              try {
                if (file_doc === null) {
                  hide_overlay();
                  reject(frappe.throw(__("File upload failed!")));
                }
                me2.handle_send_message(file_doc.file_url, file_doc.file_name, file_doc.name);
              } catch (error) {
                console.log(error);
              }
            } else {
              try {
                const error = JSON.parse(xhr.responseText);
                const messages = JSON.parse(error._server_messages);
                const errorObj = JSON.parse(messages[0]);
                hide_overlay();
                reject(frappe.throw(__(errorObj.message)));
              } catch (e) {
                console.log(e);
              }
            }
          }
        };
        xhr.open("POST", "/api/method/upload_file", true);
        xhr.setRequestHeader("Accept", "application/json");
        xhr.setRequestHeader("X-Frappe-CSRF-Token", frappe.csrf_token);
        let form_data = new FormData();
        form_data.append("file", file.file_obj, file.name);
        form_data.append("is_private", 0);
        form_data.append("doctype", "ClefinCode Chat Message");
        form_data.append("docname", this.profile.room);
        form_data.append("optimize", 1);
        xhr.send(form_data);
      });
    }
    setup_voice_clip_event() {
      let me2 = this;
      me2.$chat_space.on("click", ".message-bubble .audio-btn", function() {
        const audioUrl = "/private/files/";
        if (me2.audiodict === void 0 || me2.audiodict === "undefined")
          me2.audiodict = [];
        const $voiceClipContainer = $(this).closest(".voice-clip-container");
        const filename = $voiceClipContainer.data("audio");
        if (!this.audio) {
          if (filename in me2.audiodict) {
            this.audio = me2.audiodict[filename];
          } else {
            this.audio = new Audio();
            this.audio.src = audioUrl + filename;
            me2.audiodict[filename] = this.audio;
          }
          let duration = $voiceClipContainer.data("duration");
          this.audio.addEventListener("canplaythrough", () => {
            this.audio.play();
            $(this).find('[data-icon="audio-play"]').hide();
            $(this).find(".stop-btn").show();
          });
          this.audio.addEventListener("timeupdate", () => {
            let percentage = this.audio.currentTime / duration * 100;
            let remainingTime = duration - this.audio.currentTime;
            $voiceClipContainer.find(".record-sec").css("--progress-width", `${percentage}%`);
            $voiceClipContainer.find(".record-sec").css("transition", `width ${remainingTime}s linear`);
          });
          this.audio.addEventListener("ended", () => {
            $voiceClipContainer.find(".record-sec").css("--progress-width", "0%");
            $voiceClipContainer.find(".record-sec").css("transition", "none");
            $(this).find(".stop-btn").hide();
            $(this).find('[data-icon="audio-play"]').show();
          });
        } else {
          if (this.audio.paused) {
            this.audio.play();
            $(this).find('[data-icon="audio-play"]').hide();
            $(this).find(".stop-btn").show();
          } else {
            this.audio.pause();
            $(this).find(".stop-btn").hide();
            $(this).find('[data-icon="audio-play"]').show();
          }
          if (!(filename in me2.audiodict)) {
            me2.audiodict[filename] = this.audio;
          }
        }
        for (let audio in me2.audiodict) {
          if (me2.audiodict[audio] != this.audio) {
            let $cont = $(".voice-clip-container[data-audio='" + audio + "']");
            if ($cont.length > 0) {
              $cont.find(".stop-btn").hide();
              $cont.find('[data-icon="audio-play"]').show();
            }
            me2.audiodict[audio].pause();
          }
        }
      });
      me2.$chat_space.on(
        "click",
        ".message-bubble .record-canvas",
        function(event) {
          const $voiceClipContainer = $(this).closest(".voice-clip-container");
          const filename = $voiceClipContainer.data("audio");
          const duration = $voiceClipContainer.data("duration");
          let audio = null;
          if (!me2.audiodict[filename]) {
            const audioUrl = "/private/files/" + filename;
            audio = new Audio(audioUrl);
            me2.audiodict[filename] = audio;
          } else {
            audio = me2.audiodict[filename];
          }
          const rect = this.getBoundingClientRect();
          const x = event.clientX - rect.left;
          const totalWidth = $(this).width();
          const clickPositionRatio = x / totalWidth;
          const audioTime = clickPositionRatio * duration;
          audio.currentTime = audioTime;
          const percentage = audio.currentTime / duration * 100;
          $voiceClipContainer.find(".record-sec").css("--progress-width", `${percentage}%`);
        }
      );
    }
    async check_if_contact_has_chat(user_email, contact, contact_name, platform2 = "test") {
      const me2 = this;
      const room = await check_if_contact_has_chat(user_email, contact, platform2);
      if (room.results.name) {
        this.open_chat_space(contact, contact_name, platform2, room.results.name);
      } else {
        this.open_chat_space(contact, contact_name, platform2);
      }
    }
    open_chat_space(contact, contact_name, platform2, room = null) {
      if (room) {
        if (check_if_chat_window_open(room, "room")) {
          $(".expand-chat-window[data-id|='" + room + "']").click();
          return;
        }
        this.chat_window = new ChatWindow({
          profile: {
            room
          }
        });
        let profile = {
          is_admin: this.profile.is_admin,
          user: this.profile.user,
          user_email: this.profile.user_email,
          time_zone: this.profile.time_zone,
          room,
          room_name: contact_name,
          room_type: "Direct",
          contact,
          is_first_message: 0,
          platform: platform2
        };
        this.chat_space = new ChatSpace({
          $wrapper: this.chat_window.$chat_window,
          profile
        });
      } else {
        if (check_if_chat_window_open(contact, "contact")) {
          $(".expand-chat-window[data-id|='" + contact + "']").click();
          return;
        }
        this.chat_window = new ChatWindow({
          profile: {
            contact,
            platform: platform2
          }
        });
        let profile = {
          is_admin: this.profile.is_admin,
          user: this.profile.user,
          user_email: this.profile.user_email,
          time_zone: this.profile.time_zone,
          room: null,
          room_name: contact_name,
          room_type: "Direct",
          contact,
          is_first_message: 1,
          platform: platform2
        };
        this.chat_space = new ChatSpace({
          $wrapper: this.chat_window.$chat_window,
          profile
        });
      }
    }
